import React, { useRef } from 'react';
 import './UserStatus.css';
 import userPic from '../rachel.jpeg';
 import posts from "../data/db.json";



 function UserStatus({setPostsList,postsList}) {

     const addPost = () => {
         const post = {
             "id": 11,
             "userPic": "birthday.jpg",
             "name":"new",
             "text": "bla bla" ,
             "photo": "img10",
             "likes": "45",
             "comments": "80"
         }
         setPostsList([...postsList,post])
     }
   const searchBox = useRef(null)
   const search =function(searchBox){
     console.log(searchBox.current.valu)
   }

     return (
         <div class="card">
             <div class="card-body">
                 <div class="row">
                     <div class = "enterStatuse">
                        <div class = "statusePic">
                     <img src={userPic} onKeyUp={search} class="card-img-bottom-user" alt="userPec"></img>
                     </div>
                     <div statusetext>
                     <form class="d-flex" role="search">
                         <input ref={searchBox} class="form-control" type="search" placeholder="What's on your mind?"
                             aria-label="Search"></input>
                     </form>
                     </div> 

                 </div>
                 </div>
                 <div class = "statusButton">
                 <button type="button" class="btn btn-light" onClick={addPost}>Post</button>
                     <button type="button" class="btn btn-light">Live video</button>
                     <button type="button" class="btn btn-light">Photo/video</button>
                     <button type="button" class="btn btn-light">Feeling/activity</button>
                 </div>
             </div>
             </div>
             );
 }
             export default UserStatus;
